1|// Scene isolation check: no scene route may ship another scene's text.
2|// Scans the prerendered HTML and RSC files of a few scene routes for
3|// excerpts of neighboring scenes' paragraphs. Run after `npm run build`.
4|// Fails when a neighbor excerpt appears, or when the scene's own text is
5|// missing (which would prove the scan itself is blind).
6|import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
7|import { dirname, join } from "node:path";
8|import { fileURLToPath } from "node:url";
9|
10|const root = join(dirname(fileURLToPath(import.meta.url)), "..");
11|const EXCERPT_LEN = 80;
12|const MIN_EXCERPT_LEN = 40;
13|// First, middle, and last scenes, so both edges are covered.
14|const SAMPLE_AT = [0, 1, 0.5, -2, -1];
15|
16|export function unescapePayload(text) {
17|  return text
18|    .replace(/\\u([0-9a-fA-F]{4})/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
19|    .replace(/\\[nrt]/g, "")
20|    .replace(/\\"/g, '"')
21|    .replace(/\\\\/g, "\\")
22|    .replace(/&#x([0-9a-fA-F]+);/g, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
23|    .replace(/&#(\d+);/g, (_, dec) => String.fromCharCode(Number(dec)))
24|    .replace(/&quot;/g, '"')
25|    .replace(/&amp;/g, "&")
26|    .replace(/&lt;/g, "<")
27|    .replace(/&gt;/g, ">");
28|}
29|
30|// Lowercase alphanumeric only, so JSON/HTML escaping and whitespace
31|// differences cannot hide a leak.
32|export function normalize(text) {
33|  return unescapePayload(text)
34|    .toLowerCase()
35|    .replace(/[^\p{L}\p{N}]+/gu, "");
36|}
37|
38|export function excerpt(text) {
39|  return normalize(text).slice(0, EXCERPT_LEN);
40|}
41|
42|function loadScenes() {
43|  const book = JSON.parse(readFileSync(join(root, "data/books/oz/book.json"), "utf8"));
44|  const analysis = JSON.parse(readFileSync(join(root, "data/books/oz/analysis.json"), "utf8"));
45|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
46|  return analysis.scenes.map((scene) => ({
47|    id: scene.id,
48|    texts: Array.from({ length: scene.end_n - scene.start_n + 1 }, (_, i) => byN.get(scene.start_n + i) ?? ""),
49|  }));
50|}
51|
52|function routeFiles(sceneId) {
53|  const dir = join(root, ".next/server/app/leer");
54|  const names = existsSync(dir) ? readdirSync(dir) : [];
55|  const own = [`${sceneId}.html`, `${sceneId}.rsc`];
56|  const segments = names.filter((n) => n === `${sceneId}.segments`);
57|  const files = [];
58|  for (const name of own) {
59|    const path = join(dir, name);
60|    if (existsSync(path)) files.push(path);
61|  }
62|  for (const seg of segments) {
63|    for (const name of readdirSync(join(dir, seg))) {
64|      const path = join(dir, seg, name);
65|      if (statSync(path).isFile()) files.push(path);
66|    }
67|  }
68|  return files;
69|}
70|
71|export function checkIsolation({ scenes, readFile = (p) => readFileSync(p, "utf8"), filesFor = routeFiles } = {}) {
72|  const list = scenes ?? loadScenes();
73|  const at = SAMPLE_AT.map((i) => (i < 0 ? list.length + i : Math.floor(list.length * i)));
74|  const failures = [];
75|  for (const i of at) {
76|    const scene = list[i];
77|    if (!scene) continue;
78|    const files = filesFor(scene.id);
79|    if (files.length === 0) {
80|      failures.push(`${scene.id}: no prerendered files (run npm run build first)`);
81|      continue;
82|    }
83|    const haystack = files.map((f) => normalize(readFile(f))).join("\n");
84|    const own = excerpt(scene.texts[0] ?? "");
85|    if (own.length >= MIN_EXCERPT_LEN && !haystack.includes(own)) {
86|      failures.push(`${scene.id}: own text missing, the scan is blind`);
87|    }
88|    for (const neighbor of [list[i - 1], list[i + 1]]) {
89|      if (!neighbor) continue;
90|      for (const text of neighbor.texts.slice(0, 2)) {
91|        const probe = excerpt(text);
92|        if (probe.length < MIN_EXCERPT_LEN) continue;
93|        if (haystack.includes(probe)) {
94|          failures.push(`${scene.id}: leaks text of neighbor ${neighbor.id}`);
95|          break;
96|        }
97|      }
98|    }
99|  }
100|  return failures;
101|}
102|
103|if (process.argv[1] === fileURLToPath(import.meta.url)) {
104|  const failures = checkIsolation();
105|  if (failures.length > 0) {
106|    for (const failure of failures) console.error(`isolation: ${failure}`);
107|    process.exit(1);
108|  }
109|  console.log("isolation: sampled scene routes carry no neighbor text");
110|}

