167|// True only when the scene id changed. The container gates observeScene
168|// on this, so sub-page moves never touch the scheduler.
169|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
170|  return prevSceneId !== nextSceneId;
171|}
172|
173|export function observeSceneEntry(
174|  prevSceneId: string | null,
175|  nextSceneId: string,
176|  observe: (sceneId: string) => void,
177|): void {
178|  if (isSceneEntry(prevSceneId, nextSceneId)) observe(nextSceneId);
179|}
