267|            playlistOn={playlistOn}
268|            playlistLabel={activePlaylist?.label ?? null}
269|            onTogglePlaylist={togglePlaylist}
270|            controlsDisabled={playlistOn}
271|          />
272|        )}
273|      </div>
274|      {children}
275|    </>
276|  );
