93|// The only text a scene route ships: this scene, its chapter, its pages,
94|// and neighbor ids for the pager. Throws on unknown scene id.
95|export function buildSceneView(
96|  model: ReaderModel,
97|  sceneId: string,
98|  budgetWords: number = PAGE_WORD_BUDGET,
99|): SceneView {
100|  const flat = model.chapters.flatMap((c) => c.scenes.map((s) => ({ ch: c.ch, chapterTitle: c.title, scene: s })));
101|  const at = flat.findIndex((e) => e.scene.id === sceneId);
102|  if (at < 0 || !flat[at]) throw new Error(`unknown scene ${sceneId}`);
103|  const entry = flat[at] as { ch: number; chapterTitle: string; scene: ReaderScene };
104|  const chapterScenes = flat.filter((e) => e.ch === entry.ch);
105|  const prev = at > 0 ? flat[at - 1] : null;
106|  const next = at < flat.length - 1 ? flat[at + 1] : null;
107|  return {
108|    sceneId,
109|    ch: entry.ch,
110|    chapterTitle: entry.chapterTitle,
111|    title: entry.scene.title,
112|    emotion: entry.scene.emotion,
113|    pages: paginateScene(entry.scene.paragraphs, budgetWords),
114|    prevSceneId: prev?.scene.id ?? null,
115|    nextSceneId: next?.scene.id ?? null,
116|    prevPages: prev ? paginateScene(prev.scene.paragraphs, budgetWords).length : 0,
117|    k: chapterScenes.findIndex((e) => e.scene.id === sceneId) + 1,
118|    n: chapterScenes.length,
119|  };
