127|export type NavAction =
128|  | { kind: "next" }
129|  | { kind: "prev" }
130|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
131|
132|export interface NavIndex {
133|  order: string[];
134|  pageCounts: Map<string, number>;
135|}
136|
137|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
138|  return {
139|    order: views.map((v) => v.sceneId),
140|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
141|  };
