144|// Every pager move in one place: next/prev cross scenes and chapters,
145|// going back lands on the last sub-page, bounds are no-ops, unknown
146|// goto ids keep state.
147|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
148|  const at = index.order.indexOf(state.sceneId);
149|  if (at < 0) return state;
150|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
151|  if (action.kind === "next") {
152|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
153|    const nextId = index.order[at + 1];
154|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
155|  }
156|  if (action.kind === "prev") {
157|    if (state.page > 0) return { ...state, page: state.page - 1 };
158|    const prevId = at > 0 ? index.order[at - 1] : undefined;
159|    if (prevId === undefined) return state;
160|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
161|  }
162|  if (index.order.indexOf(action.sceneId) < 0) return state;
163|  const count = index.pageCounts.get(action.sceneId) ?? 1;
164|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
