181|// Throws on unordered scenes and on paragraphs covered zero or two times.
182|export function buildReaderModel(
183|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
184|  analysis: { scenes: AnalyzedScene[] },
185|): ReaderModel {
186|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
187|  const scenes = [...analysis.scenes];
188|  for (let i = 1; i < scenes.length; i++) {
189|    const prev = scenes[i - 1];
190|    const cur = scenes[i];
191|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
192|      throw new Error(`scenes out of order at ${cur.id}`);
193|    }
194|  }
195|  const seen = new Set<number>();
196|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
197|  for (const scene of scenes) {
198|    const paras: ReaderParagraph[] = [];
199|    for (let n = scene.start_n; n <= scene.end_n; n++) {
200|      const p = byN.get(n);
201|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
202|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
203|      seen.add(n);
204|      paras.push({ id: p.id, n: p.n, text: p.text });
205|    }
206|    sceneParagraphs.set(scene.id, paras);
207|  }
208|  if (seen.size !== book.paragraphs.length) {
209|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
210|  }
211|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
212|    const mine = scenes.filter((s) => s.ch === chapter.ch);
213|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
214|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
215|    }
216|    return {
217|      ch: chapter.ch,
218|      title: chapter.title,
219|      scenes: mine.map((s) => ({
220|        id: s.id,
221|        title: s.title,
222|        emotion: s.final === null ? null : { ...s.final },
223|        paragraphs: sceneParagraphs.get(s.id) ?? [],
224|      })),
225|    };
226|  });
227|  return {
228|    bookId: book.id,
229|    textVersion: book.textVersion,
230|    title: book.title,
231|    author: book.author,
232|    chapters,
233|  };
